package org.apache.commons.compress.utils;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.Closeable;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class IOUtils_skip_TriageGen1Test {

    @Test
    public void testSkip_ZeroNumToSkip() throws IOException {
        byte[] data = "Hello World".getBytes();
        InputStream input = new ByteArrayInputStream(data);
        long skipped = IOUtils.skip(input, 0);
        assertEquals(0L, skipped);
    }

    @Test
    public void testSkip_SuccessfulSkipViaSkipMethod() throws IOException {
        byte[] data = "0123456789".getBytes();
        InputStream input = new ByteArrayInputStream(data);
        // Most ByteArrayInputStream.skip() implementations will handle this directly
        long skipped = IOUtils.skip(input, 5);
        assertEquals(5L, skipped);
        assertEquals('5', (char) input.read());
    }

    @Test
    public void testSkip_PartialSkipThenReadFully() throws IOException {
        // We need an InputStream that returns 0 for skip() to trigger the readFully logic
        InputStream partialSkipStream = new InputStream() {
            private int pos = 0;
            private final byte[] data = "0123456789".getBytes();

            @Override
            public int read() throws IOException {
                if (pos >= data.length) return -1;
                return data[pos++] & 0xFF;
            }

            @Override
            public long skip(long n) throws IOException {
                // Force skip to return 0 to trigger the second while loop (readFully logic)
                return 0;
            }
        };

        long skipped = IOUtils.skip(partialSkipStream, 5);
        assertEquals(5L, skipped);
        assertEquals('5', (char) partialSkipStream.read());
    }

    @Test
    public void testSkip_SkipMoreThanAvailable() throws IOException {
        byte[] data = "123".getBytes();
        InputStream input = new ByteArrayInputStream(data);
        // Try to skip 10 bytes when only 3 exist
        long skipped = IOUtils.skip(input, 10);
        assertEquals(3L, skipped);
    }

    @Test
    public void testSkip_TriggersReadFullyLoopUntilEnd() throws IOException {
        // Stream that returns 0 for skip, forcing the readFully loop
        InputStream stream = new InputStream() {
            private int pos = 0;
            private final byte[] data = "ABC".getBytes();

            @Override
            public int read() throws IOException {
                if (pos >= data.length) return -1;
                return data[pos++] & 0xFF;
            }

            @Override
            public long skip(long n) throws IOException {
                return 0; 
            }
        };

        // numToSkip is large, should stop when read < 1
        long skipped = IOUtils.skip(stream, 100);
        assertEquals(3L, skipped);
    }

    @Test
    public void testSkip_SkipViaReadFullyWithBufferBoundaries() throws IOException {
        // This tests the logic: (int) Math.min(numToSkip, SKIP_BUF_SIZE)
        // We use a custom stream to ensure skip() returns 0
        InputStream stream = new InputStream() {
            private int pos = 0;
            private final byte[] data = new byte[100];
            {
                for(int i=0; i<100; i++) data[i] = (byte) i;
            }

            @Override
            public int read() throws IOException {
                if (pos >= data.length) return -1;
                return data[pos++] & 0xFF;
            }

            @Override
            public long skip(long n) throws IOException {
                return 0;
            }
        };

        // Assuming SKIP_BUF_SIZE is a constant in IOUtils. 
        // We skip a value that is likely larger than the buffer to ensure multiple iterations.
        long skipped = IOUtils.skip(stream, 50);
        assertEquals(50L, skipped);
    }

    @Test(expected = IOException.class)
    public void testSkip_ThrowsIOException() throws IOException {
        InputStream errorStream = new InputStream() {
            @Override
            public int read() throws IOException {
                throw new IOException("Simulated error");
            }
            @Override
            public long skip(long n) throws IOException {
                throw new IOException("Simulated error");
            }
        };
        IOUtils.skip(errorStream, 5);
    }
}
